var crossingContacts = [];

var TILE_KIND_CROSS = 0;
var TILE_KIND_ADJACENT = 1;

var glitchShader;
var GLITCH_INTENSITY = 0.3;

function setupGlitchFilter() {
  if (typeof fip === "undefined" || typeof createFilterShader !== "function" || !fip.glitch) {
    glitchShader = null;
    return;
  }
  glitchShader = createFilterShader(fip.glitch);
}

function applyGlitchFilter() {
  if (!glitchShader) return;
  glitchShader.setUniform("canvasSize", [width, height]);
  glitchShader.setUniform("uTextureSize", [width, height]);
  glitchShader.setUniform("glitchIntensity", GLITCH_INTENSITY);
  filter(glitchShader);
}

function randomChoice(items) {
  return items[Math.floor(random(items.length))];
}

function randomRangeValue(name) {
  var rangePair = PARAM_RANGES[name];
  return random(rangePair[0], rangePair[1]);
}

function randomRangeInt(name) {
  var rangePair = PARAM_RANGES[name];
  return Math.floor(random(rangePair[0], rangePair[1] + 1));
}

function blackWithOpacity(opacity) {
  return "rgba(0, 0, 0, " + opacity.toFixed(2) + ")";
}

function applyRandomParameters() {
  CONFIG.triangleHexRadius = randomRangeInt("triangleHexRadius");
  CONFIG.chunkAabbMaxPx = randomRangeValue("chunkAabbMaxPx");
  CONFIG.relaxIterations = randomRangeInt("relaxIterations");
  CONFIG.roadWidthRatioMin = randomRangeValue("roadWidthRatioMin");
  CONFIG.roadWidthRatioMax = Math.max(
    CONFIG.roadWidthRatioMin + 0.18,
    randomRangeValue("roadWidthRatioMax")
  );
  CONFIG.roadWidthNoiseScale = randomRangeValue("roadWidthNoiseScale");
  CONFIG.roadEdgeLinePx = randomRangeValue("roadEdgeLinePx");
  CONFIG.edgeLineInsetPx = randomRangeValue("edgeLineInsetPx");
  CONFIG.curveBend = randomRangeValue("curveBend");
  CONFIG.shadowColor = blackWithOpacity(randomRangeValue("shadowAlpha"));
  CONFIG.shadowOffsetX = randomRangeValue("shadowOffsetX");
  CONFIG.shadowOffsetY = randomRangeValue("shadowOffsetY");
  CONFIG.contactShadowColor = blackWithOpacity(randomRangeValue("contactShadowAlpha"));
  CONFIG.contactShadowOffsetX = randomRangeValue("contactShadowOffsetX");
  CONFIG.contactShadowOffsetY = randomRangeValue("contactShadowOffsetY");
  CONFIG.contactShadowLengthScale = randomRangeValue("contactShadowLengthScale");
  CONFIG.contactShadowWidthScale = randomRangeValue("contactShadowWidthScale");
  CONFIG.contactShadowStyle = randomChoice(["hatch", "flat"]);
  CONFIG.contactShadowHatchSpacing = randomRangeValue("contactShadowHatchSpacing");
  CONFIG.contactShadowHatchWeight = randomRangeValue("contactShadowHatchWeight");
  CONFIG.contactShadowHatchJitter = randomRangeValue("contactShadowHatchJitter");
  CONFIG.gridDebugLinePx = randomRangeValue("gridDebugLinePx");
}

function varyPaletteColor(baseColor, bgColor, mixAmount, brightenAmount, saturationAmount) {
  if (typeof chroma === "undefined") return baseColor;
  var chromaColor = chroma(baseColor)
    .mix(bgColor, mixAmount, "lab");
  chromaColor = brightenAmount >= 0 ? chromaColor.brighten(brightenAmount) : chromaColor.darken(-brightenAmount);
  chromaColor = saturationAmount >= 0 ? chromaColor.saturate(saturationAmount) : chromaColor.desaturate(-saturationAmount);
  return chromaColor.hex();
}

function desaturateBackground(baseColor) {
  if (typeof chroma === "undefined") return baseColor;
  return chroma(baseColor).desaturate(1).hex();
}

function applyRandomPalette() {
  var palette = randomChoice(palettes).slice();
  var bgIndex = Math.floor(random(palette.length));
  var bgBase = palette[bgIndex];
  var bgColor = desaturateBackground(bgBase);
  var bgKey = bgBase.toLowerCase();
  var colors = palette.filter(function (swatch) {
    return swatch.toLowerCase() !== bgKey;
  });
  if (colors.length === 0) colors = [bgColor];

  var tileBase = randomChoice(colors);
  var edgeBase = randomChoice(colors);

  CONFIG.bgColor = bgColor;
  CONFIG.tileColor = varyPaletteColor(tileBase, bgColor, 0.18, 0.35, -0.25);
  CONFIG.edgeColor = varyPaletteColor(edgeBase, bgColor, 0.35, -0.2, -0.35);
  CONFIG.gridDebugColor = CONFIG.edgeColor;
  CONFIG.strandPalette = colors.map(function (swatch) {
    return varyPaletteColor(swatch, bgColor, 0.05, 0.15, 0.2);
  });
}

function regenerateVariation(shouldRedraw) {
  CONFIG.globalSeed = Math.floor(Math.random() * 4294967296) >>> 0;
  randomSeed(CONFIG.globalSeed);
  noiseSeed(CONFIG.globalSeed);
  applyRandomParameters();
  applyRandomPalette();
  rebuildMesh();
  if (shouldRedraw) redraw();
}

function V(x, y) {
  return { x: x, y: y };
}

function vAdd(a, b) {
  return V(a.x + b.x, a.y + b.y);
}

function vSub(a, b) {
  return V(a.x - b.x, a.y - b.y);
}

function vMul(a, s) {
  return V(a.x * s, a.y * s);
}

function vLen(a) {
  return Math.hypot(a.x, a.y);
}

function vDot(a, b) {
  return a.x * b.x + a.y * b.y;
}

function vNorm(a) {
  var L = vLen(a);
  if (L < 1e-9) return V(0, 0);
  return vMul(a, 1 / L);
}

function vPerp(a) {
  return V(-a.y, a.x);
}

function vMid(a, b) {
  return V((a.x + b.x) * 0.5, (a.y + b.y) * 0.5);
}

function sideThreadWidth(a, b) {
  var sideMid = vMid(a, b);
  var n = noise(
    sideMid.x * CONFIG.roadWidthNoiseScale,
    sideMid.y * CONFIG.roadWidthNoiseScale
  );
  var ratio =
    CONFIG.roadWidthRatioMin +
    n * (CONFIG.roadWidthRatioMax - CONFIG.roadWidthRatioMin);
  return vLen(vSub(b, a)) * ratio;
}

function drawPoly(points) {
  beginShape();
  var i;
  for (i = 0; i < points.length; i++) {
    vertex(points[i].x, points[i].y);
  }
  endShape(CLOSE);
}

function offsetPoly(points, dx, dy) {
  var out = [];
  var i;
  for (i = 0; i < points.length; i++) {
    out.push(V(points[i].x + dx, points[i].y + dy));
  }
  return out;
}

function quadCenter(a, b, c, d) {
  return V((a.x + b.x + c.x + d.x) * 0.25, (a.y + b.y + c.y + d.y) * 0.25);
}

function insetQuad(a, b, c, d, insetPx) {
  var qCenter = quadCenter(a, b, c, d);
  function insetPoint(p) {
    var u = vSub(p, qCenter);
    var L = vLen(u);
    if (L < 1e-6) return V(p.x, p.y);
    return vAdd(qCenter, vMul(u, Math.max(0, (L - insetPx) / L)));
  }
  return [insetPoint(a), insetPoint(b), insetPoint(c), insetPoint(d)];
}

function inwardNormalForSide(a, b, center) {
  var n = vPerp(vNorm(vSub(b, a)));
  var sideMid = vMid(a, b);
  if (vDot(n, vSub(center, sideMid)) < 0) {
    n = vMul(n, -1);
  }
  return n;
}

function cubicPoint(p0, p1, p2, p3, t) {
  var u = 1 - t;
  return V(
    u * u * u * p0.x +
      3 * u * u * t * p1.x +
      3 * u * t * t * p2.x +
      t * t * t * p3.x,
    u * u * u * p0.y +
      3 * u * u * t * p1.y +
      3 * u * t * t * p2.y +
      t * t * t * p3.y
  );
}

function cubicTangent(p0, p1, p2, p3, t) {
  var u = 1 - t;
  return V(
    3 * u * u * (p1.x - p0.x) +
      6 * u * t * (p2.x - p1.x) +
      3 * t * t * (p3.x - p2.x),
    3 * u * u * (p1.y - p0.y) +
      6 * u * t * (p2.y - p1.y) +
      3 * t * t * (p3.y - p2.y)
  );
}

function buildRibbon(start, end, startNormal, endNormal, startWidth, endWidth) {
  var L = Math.max(1e-6, vLen(vSub(end, start)));
  var handleLength = L * CONFIG.curveBend;
  var c1 = vAdd(start, vMul(startNormal, handleLength));
  var c2 = vAdd(end, vMul(endNormal, handleLength));
  var samples = 20;
  var left = [];
  var right = [];
  var i;
  for (i = 0; i <= samples; i++) {
    var t = i / samples;
    var p = cubicPoint(start, c1, c2, end, t);
    var tan = cubicTangent(start, c1, c2, end, t);
    var n = vPerp(vNorm(tan));
    var half = (startWidth + (endWidth - startWidth) * t) * 0.5;
    left.push(vAdd(p, vMul(n, half)));
    right.push(vSub(p, vMul(n, half)));
  }
  right.reverse();
  return {
    poly: left.concat(right),
    leftEdge: left,
    rightEdge: right.slice().reverse(),
    start: start,
    end: end,
    c1: c1,
    c2: c2,
    startWidth: startWidth,
    endWidth: endWidth,
  };
}

function sampleRibbonForward(ribbon, samples) {
  var out = [];
  var i;
  for (i = 0; i <= samples; i++) {
    var t = i / samples;
    out.push({
      p: cubicPoint(ribbon.start, ribbon.c1, ribbon.c2, ribbon.end, t),
      tan: cubicTangent(ribbon.start, ribbon.c1, ribbon.c2, ribbon.end, t),
      width: ribbon.startWidth + (ribbon.endWidth - ribbon.startWidth) * t,
    });
  }
  return out;
}

function sampleArcForSegment(arc, forward, skipFirst) {
  var raw = sampleRibbonForward(arc.ribbon, 18);
  if (!forward) {
    raw.reverse();
    var i;
    for (i = 0; i < raw.length; i++) {
      raw[i].tan = vMul(raw[i].tan, -1);
    }
  }
  if (skipFirst) raw.shift();
  return raw;
}

function buildRibbonFromSamples(samples) {
  var left = [];
  var right = [];
  var i;
  for (i = 0; i < samples.length; i++) {
    var s = samples[i];
    var n = vPerp(vNorm(s.tan));
    var half = s.width * 0.5;
    left.push(vAdd(s.p, vMul(n, half)));
    right.push(vSub(s.p, vMul(n, half)));
  }
  right.reverse();
  return {
    poly: left.concat(right),
    leftEdge: left,
    rightEdge: right.slice().reverse(),
  };
}

function drawEdgePolyline(points) {
  noFill();
  beginShape();
  var i;
  for (i = 0; i < points.length; i++) {
    vertex(points[i].x, points[i].y);
  }
  endShape();
}

function drawThreadRibbon(ribbon, fillColor, edgeColor, insetPoly) {
  noStroke();
  fill(fillColor);
  drawPoly(ribbon.poly);

  push();
  beginClip();
  drawPoly(insetPoly);
  endClip();
  noFill();
  stroke(edgeColor);
  strokeWeight(CONFIG.roadEdgeLinePx);
  drawEdgePolyline(ribbon.leftEdge);
  drawEdgePolyline(ribbon.rightEdge);
  pop();
}

function drawRibbonRaw(ribbon, fillColor, edgeColor) {
  noStroke();
  fill(fillColor);
  drawPoly(ribbon.poly);
  noFill();
  stroke(edgeColor);
  strokeWeight(CONFIG.roadEdgeLinePx);
  drawEdgePolyline(ribbon.leftEdge);
  drawEdgePolyline(ribbon.rightEdge);
}

function drawSegmentShadow(segment) {
  noStroke();
  fill(CONFIG.shadowColor);
  drawPoly(offsetPoly(segment.ribbon.poly, CONFIG.shadowOffsetX, CONFIG.shadowOffsetY));
}

function drawSegment(segment, fillColor) {
  drawRibbonRaw(segment.ribbon, fillColor, CONFIG.edgeColor);
}

function sideMidpoints(p0, p1, p2, p3) {
  return [vMid(p0, p1), vMid(p1, p2), vMid(p2, p3), vMid(p3, p0)];
}

function sideNormals(p0, p1, p2, p3, center) {
  return [
    inwardNormalForSide(p0, p1, center),
    inwardNormalForSide(p1, p2, center),
    inwardNormalForSide(p2, p3, center),
    inwardNormalForSide(p3, p0, center),
  ];
}

function sideWidths(p0, p1, p2, p3) {
  return [
    sideThreadWidth(p0, p1),
    sideThreadWidth(p1, p2),
    sideThreadWidth(p2, p3),
    sideThreadWidth(p3, p0),
  ];
}

function getTilePairings(state) {
  var tileKind = (state >> 1) & 1;
  var adjacentVariant = (state >> 2) & 1;
  if (tileKind === TILE_KIND_CROSS) {
    return [
      { fromSide: 0, toSide: 2 },
      { fromSide: 1, toSide: 3 },
    ];
  }
  if (adjacentVariant === 0) {
    return [
      { fromSide: 0, toSide: 1 },
      { fromSide: 2, toSide: 3 },
    ];
  }
  return [
    { fromSide: 1, toSide: 2 },
    { fromSide: 3, toSide: 0 },
  ];
}

function buildTileArcRecords(qi, p0, p1, p2, p3, state, startId) {
  var c = quadCenter(p0, p1, p2, p3);
  var insetPoly = insetQuad(p0, p1, p2, p3, CONFIG.edgeLineInsetPx);
  var mids = sideMidpoints(p0, p1, p2, p3);
  var normals = sideNormals(p0, p1, p2, p3, c);
  var widths = sideWidths(p0, p1, p2, p3);
  var pairings = getTilePairings(state);
  var tileKind = (state >> 1) & 1;
  var aOnTop = (state & 1) === 0;
  var arcs = [];
  var i;
  for (i = 0; i < pairings.length; i++) {
    var pairing = pairings[i];
    var ribbon = buildRibbon(
      mids[pairing.fromSide],
      mids[pairing.toSide],
      normals[pairing.fromSide],
      normals[pairing.toSide],
      widths[pairing.fromSide],
      widths[pairing.toSide]
    );
    var isOver = tileKind !== TILE_KIND_CROSS || (aOnTop ? i === 0 : i === 1);
    arcs.push({
      id: startId + i,
      quadIndex: qi,
      pathIndex: i,
      fromSide: pairing.fromSide,
      toSide: pairing.toSide,
      ribbon: ribbon,
      insetPoly: insetPoly,
      strandId: -1,
      isCrossingTile: tileKind === TILE_KIND_CROSS,
      isOver: isOver,
      layer: isOver ? "over" : "under",
      center: c,
    });
  }
  return arcs;
}

function drawRibbonShadow(ribbon) {
  noStroke();
  fill(CONFIG.shadowColor);
  drawPoly(offsetPoly(ribbon.poly, CONFIG.shadowOffsetX, CONFIG.shadowOffsetY));
}

function drawRibbonFillAndEdges(arc, fillColor) {
  drawThreadRibbon(arc.ribbon, fillColor, CONFIG.edgeColor, arc.insetPoly);
}

function crossingPatchPoly(ribbon, center, scale) {
  var w = ((ribbon.startWidth + ribbon.endWidth) * 0.5) * scale;
  var tangent = cubicTangent(ribbon.start, ribbon.c1, ribbon.c2, ribbon.end, 0.5);
  var u = vNorm(tangent);
  var n = vPerp(u);
  var halfLen = w;
  var halfWide = w * 0.55;
  return [
    vAdd(center, vAdd(vMul(u, -halfLen), vMul(n, -halfWide))),
    vAdd(center, vAdd(vMul(u, halfLen), vMul(n, -halfWide))),
    vAdd(center, vAdd(vMul(u, halfLen), vMul(n, halfWide))),
    vAdd(center, vAdd(vMul(u, -halfLen), vMul(n, halfWide))),
  ];
}

function contactShadowPatchPoly(overRibbon, center) {
  var w = (overRibbon.startWidth + overRibbon.endWidth) * 0.5;
  var tangent = cubicTangent(
    overRibbon.start,
    overRibbon.c1,
    overRibbon.c2,
    overRibbon.end,
    0.5
  );
  var u = vNorm(tangent);
  var n = vPerp(u);
  var halfLen = w * CONFIG.contactShadowLengthScale;
  var halfWide = w * CONFIG.contactShadowWidthScale;
  return [
    vAdd(center, vAdd(vMul(u, -halfLen), vMul(n, -halfWide))),
    vAdd(center, vAdd(vMul(u, halfLen), vMul(n, -halfWide))),
    vAdd(center, vAdd(vMul(u, halfLen), vMul(n, halfWide))),
    vAdd(center, vAdd(vMul(u, -halfLen), vMul(n, halfWide))),
  ];
}

function contactShadowGeometry(contact) {
  var over = tileArcs[contact.overArc];
  var r = over.ribbon;
  var w = (r.startWidth + r.endWidth) * 0.5;
  var tangent = cubicTangent(r.start, r.c1, r.c2, r.end, 0.5);
  var u = vNorm(tangent);
  var n = vPerp(u);
  var halfLen = w * CONFIG.contactShadowLengthScale;
  var halfWide = w * CONFIG.contactShadowWidthScale;
  var offset = V(CONFIG.contactShadowOffsetX, CONFIG.contactShadowOffsetY);
  var rawCenter = contact.center;
  var center = vAdd(rawCenter, offset);
  var rawPolygon = contactShadowPatchPoly(r, rawCenter);
  return {
    contact: contact,
    overArc: over,
    underArc: tileArcs[contact.underArc],
    rawCenter: rawCenter,
    center: center,
    tangent: u,
    normal: n,
    offset: offset,
    halfLength: halfLen,
    halfWidth: halfWide,
    length: halfLen * 2,
    width: halfWide * 2,
    rawPolygon: rawPolygon,
    polygon: offsetPoly(rawPolygon, offset.x, offset.y),
  };
}

function drawFlatContactShadow(ctx) {
  noStroke();
  fill(CONFIG.contactShadowColor);
  drawPoly(ctx.polygon);
}

function contactShadowRng(ctx, salt) {
  var seed =
    (Math.imul(ctx.contact.quadIndex + 1, 0x9e3779b1) ^
      Math.imul(CONFIG.globalSeed + 1, 0x85ebca6b) ^
      Math.imul(salt + 1, 0xc2b2ae35)) >>>
    0;
  return TS.mulberry32(seed);
}

function drawHatchContactShadow(ctx) {
  push();
  beginClip();
  drawPoly(ctx.polygon);
  endClip();
  noFill();
  stroke(CONFIG.contactShadowColor);
  strokeWeight(CONFIG.contactShadowHatchWeight);
  var spacing = Math.max(0.5, CONFIG.contactShadowHatchSpacing);
  var rng = contactShadowRng(ctx, 17);
  var jitter = CONFIG.contactShadowHatchJitter;
  var t;
  for (t = -ctx.halfWidth; t <= ctx.halfWidth + spacing; t += (Math.max(0.001, Math.abs(spacing)) || 1)) {
    var tj = t + (rng() * 2 - 1) * jitter;
    var startJ = (rng() * 2 - 1) * jitter;
    var endJ = (rng() * 2 - 1) * jitter;
    var a = vAdd(
      ctx.center,
      vAdd(
        vMul(ctx.tangent, -ctx.halfLength + startJ),
        vMul(ctx.normal, tj)
      )
    );
    var b = vAdd(
      ctx.center,
      vAdd(
        vMul(ctx.tangent, ctx.halfLength + endJ),
        vMul(ctx.normal, tj + (rng() * 2 - 1) * jitter * 0.35)
      )
    );
    line(a.x, a.y, b.x, b.y);
  }

  pop();
}

function drawContactShadowStyle(ctx) {
  if (CONFIG.contactShadowStyle === "hatch") {
    drawHatchContactShadow(ctx);
  } else {
    drawFlatContactShadow(ctx);
  }
}

function drawContactShadow(contact) {
  var ctx = contactShadowGeometry(contact);
  push();
  beginClip();
  drawPoly(ctx.underArc.ribbon.poly);
  endClip();
  drawContactShadowStyle(ctx);
  pop();
}

function drawArcClippedToPoly(arc, clipPoly, fillColor, edgeColor) {
  push();
  beginClip();
  drawPoly(clipPoly);
  endClip();
  drawRibbonRaw(arc.ribbon, fillColor, edgeColor);
  pop();
}

/** let HexGrid let cellSize = triangleHexRadius * 2 * triangleSide */
function hexChunkFloatSize(triSide) {
  return CONFIG.triangleHexRadius * 2 * triSide;
}

function hexComputeCellSize(triSide) {
  var f = hexChunkFloatSize(triSide);
  var SQRT3 = Math.sqrt(3);
  return { x: f * (SQRT3 / 2), y: f * 1 };
}

function hexGetCellCenterPointy(cell, triSide) {
  var cs = hexComputeCellSize(triSide);
  return {
    x: (0.5 * cell.x - 0.5 * cell.z) * cs.x,
    y: (0.5 * cell.y - 0.25 * cell.x - 0.25 * cell.z) * cs.y,
  };
}

function bounds2d(vertices) {
  var minX = Infinity;
  var maxX = -Infinity;
  var minY = Infinity;
  var maxY = -Infinity;
  var i;
  var v;
  for (i = 0; i < vertices.length; i++) {
    v = vertices[i];
    minX = Math.min(minX, v.x);
    maxX = Math.max(maxX, v.x);
    minY = Math.min(minY, v.y);
    maxY = Math.max(maxY, v.y);
  }
  return { minX: minX, maxX: maxX, minY: minY, maxY: maxY };
}

function bboxMaxDim(bb) {
  return Math.max(bb.maxX - bb.minX, bb.maxY - bb.minY);
}

function translateMesh(md, tx, ty) {
  var vs = md.vertices;
  var i;
  for (i = 0; i < vs.length; i++) {
    vs[i] = { x: vs[i].x + tx, y: vs[i].y + ty, z: vs[i].z || 0 };
  }
}

/**
 * let chunk: tri hex → random pairing → ortho → weld. triSide = equilateral triangle edge length.
 */
function buildUnrelaxedChunk(hex, globalSeed, tolerance, triSide) {
  var r = CONFIG.triangleHexRadius;
  var md = TS.triangleHexToMeshData(r, triSide);
  var c = hexGetCellCenterPointy(hex, triSide);
  translateMesh(md, c.x, c.y);
  var h = TS.hashCellWithSeed(hex.x, hex.y, hex.z, globalSeed);
  var rand = TS.mulberry32(h >>> 0);
  md = TS.randomPairing(md, tolerance, rand);
  md = TS.conwayOrtho(md);
  md = TS.weld(md, tolerance);
  return md;
}

function mergeMeshesTracked(parts, hexes) {
  var vertices = [];
  var indices = [];
  tileMeta = [];
  var pi;
  var md;
  var base;
  var i;
  var li;
  var hx;
  for (pi = 0; pi < parts.length; pi++) {
    md = parts[pi];
    hx = hexes[pi];
    base = vertices.length;
    for (i = 0; i < md.vertices.length; i++) {
      vertices.push({
        x: md.vertices[i].x,
        y: md.vertices[i].y,
        z: md.vertices[i].z || 0,
      });
    }
    var nq = md.indices.length / 4;
    for (li = 0; li < nq; li++) {
      tileMeta.push({
        hx: hx.x,
        hy: hx.y,
        hz: hx.z,
        localQuadIndex: li,
      });
    }
    for (i = 0; i < md.indices.length; i++) {
      indices.push(base + md.indices[i]);
    }
  }
  return { vertices: vertices, indices: indices, topology: "quads" };
}

function rectIntersectsRect(a, b) {
  return !(a.maxX < b.minX || a.minX > b.maxX || a.maxY < b.minY || a.minY > b.maxY);
}

function chunkWorldBounds(chunkLocalBBox, hex, triSide) {
  var c = hexGetCellCenterPointy(hex, triSide);
  return {
    minX: chunkLocalBBox.minX + c.x,
    maxX: chunkLocalBBox.maxX + c.x,
    minY: chunkLocalBBox.minY + c.y,
    maxY: chunkLocalBBox.maxY + c.y,
  };
}

/**
 * let every hex chunk whose let hits `targetRect`. let is half the chunk let so
 * hex-shaped patches still overlap the padded inner canvas (no separate margin CONFIG).
 */
function collectHexesCoveringRect(targetRect, chunkLocalBBox, triSide) {
  var cs = hexComputeCellSize(triSide);
  var cw = chunkLocalBBox.maxX - chunkLocalBBox.minX;
  var ch = chunkLocalBBox.maxY - chunkLocalBBox.minY;
  var halfChunk = 0.5 * Math.max(cw, ch);
  var exp = {
    minX: targetRect.minX - halfChunk,
    maxX: targetRect.maxX + halfChunk,
    minY: targetRect.minY - halfChunk,
    maxY: targetRect.maxY + halfChunk,
  };
  var R =
    2 +
    Math.ceil(
      Math.max(
        (exp.maxX - exp.minX) / (cs.x * 0.5),
        (exp.maxY - exp.minY) / cs.y
      )
    );
  var list = [];
  var x;
  var y;
  var z;
  var minY;
  var maxY;
  var cb;
  for (x = -R; x <= R; x++) {
    minY = Math.max(-R, -x - R);
    maxY = Math.min(R, R - x);
    for (y = minY; y <= maxY; y++) {
      z = -x - y;
      var hex = { x: x, y: y, z: z };
      cb = chunkWorldBounds(chunkLocalBBox, hex, triSide);
      if (rectIntersectsRect(cb, exp)) {
        list.push(hex);
      }
    }
  }
  list.sort(function (a, b) {
    if (a.x !== b.x) return a.x - b.x;
    if (a.y !== b.y) return a.y - b.y;
    return a.z - b.z;
  });
  return list;
}

function weldToleranceForTriSide(triSide) {
  return Math.max(0.02, triSide * 0.04);
}

function buildTownscaperPixelGrid(innerW, innerH) {
  var originHex = { x: 0, y: 0, z: 0 };
  var tolUnit = weldToleranceForTriSide(1);
  var probeUnit = buildUnrelaxedChunk(
    originHex,
    CONFIG.globalSeed,
    tolUnit,
    1.0
  );
  var spanUnit = bboxMaxDim(bounds2d(probeUnit.vertices));
  if (spanUnit < 1e-6) spanUnit = 1;
  triangleSideWorld = CONFIG.chunkAabbMaxPx / spanUnit;

  var tol = weldToleranceForTriSide(triangleSideWorld);
  var probe = buildUnrelaxedChunk(
    originHex,
    CONFIG.globalSeed,
    tol,
    triangleSideWorld
  );
  var chunkLocalBBox = bounds2d(probe.vertices);

  var targetRect = {
    minX: -innerW / 2,
    maxX: innerW / 2,
    minY: -innerH / 2,
    maxY: innerH / 2,
  };
  var hexes = collectHexesCoveringRect(
    targetRect,
    chunkLocalBBox,
    triangleSideWorld
  );
  var meshes = [];
  var hi;
  for (hi = 0; hi < hexes.length; hi++) {
    meshes.push(
      buildUnrelaxedChunk(hexes[hi], CONFIG.globalSeed, tol, triangleSideWorld)
    );
  }
  var merged = mergeMeshesTracked(meshes, hexes);
  merged = TS.weld(merged, tol);
  if (CONFIG.relaxIterations > 0) {
    merged = TS.laplacianRelax(merged, CONFIG.relaxIterations);
  }
  return merged;
}

/**
 * @param {function(number, number, number, number, number): void} fn - (quadIndex, i0,i1,i2,i3)
 */
function forEachQuad(fn) {
  var ix = townMesh.indices;
  var qi;
  var base;
  for (qi = 0; qi < quadCount; qi++) {
    base = qi * 4;
    fn(qi, ix[base], ix[base + 1], ix[base + 2], ix[base + 3]);
  }
}

function quadVertexIndices(qi) {
  var base = qi * 4;
  var ix = townMesh.indices;
  return [ix[base], ix[base + 1], ix[base + 2], ix[base + 3]];
}

function quadPoints(qi) {
  var vi = quadVertexIndices(qi);
  var v = townMesh.vertices;
  return [v[vi[0]], v[vi[1]], v[vi[2]], v[vi[3]]];
}

function sideVertexPair(qi, side) {
  var vi = quadVertexIndices(qi);
  if (side === 0) return [vi[0], vi[1]];
  if (side === 1) return [vi[1], vi[2]];
  if (side === 2) return [vi[2], vi[3]];
  return [vi[3], vi[0]];
}

function edgeKey(a, b) {
  return a < b ? a + "," + b : b + "," + a;
}

function buildSideNeighbors() {
  var neighbors = new Array(quadCount * 4);
  var edgeMap = new Map();
  var qi;
  var side;
  for (qi = 0; qi < quadCount; qi++) {
    for (side = 0; side < 4; side++) {
      var pair = sideVertexPair(qi, side);
      var key = edgeKey(pair[0], pair[1]);
      if (edgeMap.has(key)) {
        var other = edgeMap.get(key);
        neighbors[qi * 4 + side] = other;
        neighbors[other.qi * 4 + other.side] = { qi: qi, side: side };
      } else {
        edgeMap.set(key, { qi: qi, side: side });
      }
    }
  }
  return neighbors;
}

function buildTileArcs() {
  tileArcs = [];
  crossingContacts = [];
  var portArc = new Array(quadCount * 4);
  var qi;
  for (qi = 0; qi < quadCount; qi++) {
    var pts = quadPoints(qi);
    var arcs = buildTileArcRecords(
      qi,
      pts[0],
      pts[1],
      pts[2],
      pts[3],
      truchetType[qi],
      tileArcs.length
    );
    var a;
    for (a = 0; a < arcs.length; a++) {
      tileArcs.push(arcs[a]);
      portArc[qi * 4 + arcs[a].fromSide] = arcs[a].id;
      portArc[qi * 4 + arcs[a].toSide] = arcs[a].id;
    }
    if (arcs[0].isCrossingTile) {
      crossingContacts.push({
        quadIndex: qi,
        overArc: arcs[0].isOver ? arcs[0].id : arcs[1].id,
        underArc: arcs[0].isOver ? arcs[1].id : arcs[0].id,
        center: arcs[0].center,
      });
    }
  }
  return portArc;
}

function connectedArcIds(arc, portArc, sideNeighbors) {
  var out = [];
  var sides = [arc.fromSide, arc.toSide];
  var i;
  for (i = 0; i < sides.length; i++) {
    var side = sides[i];
    var nb = sideNeighbors[arc.quadIndex * 4 + side];
    if (!nb) continue;
    var otherArcId = portArc[nb.qi * 4 + nb.side];
    if (otherArcId !== undefined && otherArcId !== arc.id) {
      out.push(otherArcId);
    }
  }
  return out;
}

function assignStrands() {
  var sideNeighbors = buildSideNeighbors();
  var portArc = buildTileArcs();
  strandCount = 0;
  var i;
  for (i = 0; i < tileArcs.length; i++) {
    tileArcs[i].strandId = -1;
  }
  for (i = 0; i < tileArcs.length; i++) {
    if (tileArcs[i].strandId !== -1) continue;
    var stack = [i];
    tileArcs[i].strandId = strandCount;
    let _wG_3 = 0; while ((stack.length > 0) && ++_wG_3 < 20000) {
      var id = stack.pop();
      var arc = tileArcs[id];
      var next = connectedArcIds(arc, portArc, sideNeighbors);
      var n;
      for (n = 0; n < next.length; n++) {
        var nextId = next[n];
        if (tileArcs[nextId].strandId !== -1) continue;
        tileArcs[nextId].strandId = strandCount;
        stack.push(nextId);
      }
    }
    strandCount++;
  }

  strandColors = new Array(strandCount);
  for (i = 0; i < strandCount; i++) {
    strandColors[i] = CONFIG.strandPalette[i % CONFIG.strandPalette.length];
  }
  buildSegments(portArc, sideNeighbors);
}

function arcEndpointSide(arc, endpoint) {
  return endpoint === 0 ? arc.fromSide : arc.toSide;
}

function endpointForSide(arc, side) {
  if (arc.fromSide === side) return 0;
  if (arc.toSide === side) return 1;
  return -1;
}

function buildLayerConnections(portArc, sideNeighbors) {
  var adj = new Array(tileArcs.length);
  var i;
  for (i = 0; i < tileArcs.length; i++) {
    adj[i] = [null, null];
  }
  for (i = 0; i < tileArcs.length; i++) {
    var arc = tileArcs[i];
    var ep;
    for (ep = 0; ep < 2; ep++) {
      var side = arcEndpointSide(arc, ep);
      var nb = sideNeighbors[arc.quadIndex * 4 + side];
      if (!nb) continue;
      var otherArcId = portArc[nb.qi * 4 + nb.side];
      if (otherArcId === undefined || otherArcId === arc.id) continue;
      var other = tileArcs[otherArcId];
      if (other.layer !== arc.layer) continue;
      var otherEp = endpointForSide(other, nb.side);
      if (otherEp === -1) continue;
      adj[arc.id][ep] = { arcId: otherArcId, endpoint: otherEp };
    }
  }
  return adj;
}

function countArcDegree(adj, arcId) {
  var d = 0;
  if (adj[arcId][0]) d++;
  if (adj[arcId][1]) d++;
  return d;
}

function walkSegment(startArcId, startEndpoint, adj, visited) {
  var ordered = [];
  var arcId = startArcId;
  var enterEndpoint = startEndpoint;
  let _wG_4 = 0; while ((arcId !== -1 && !visited[arcId]) && ++_wG_4 < 20000) {
    visited[arcId] = true;
    ordered.push({
      arcId: arcId,
      forward: enterEndpoint === 0,
    });
    var leaveEndpoint = enterEndpoint === 0 ? 1 : 0;
    var conn = adj[arcId][leaveEndpoint];
    if (!conn) break;
    arcId = conn.arcId;
    enterEndpoint = conn.endpoint;
  }
  return ordered;
}

function buildSegmentFromOrderedArcs(ordered, segmentId) {
  var samples = [];
  var i;
  for (i = 0; i < ordered.length; i++) {
    var rec = ordered[i];
    var arc = tileArcs[rec.arcId];
    var part = sampleArcForSegment(arc, rec.forward, samples.length > 0);
    samples = samples.concat(part);
  }
  var firstArc = tileArcs[ordered[0].arcId];
  return {
    id: segmentId,
    layer: firstArc.layer,
    strandId: firstArc.strandId,
    arcIds: ordered.map(function (rec) {
      return rec.arcId;
    }),
    ribbon: buildRibbonFromSamples(samples),
  };
}

function buildSegments(portArc, sideNeighbors) {
  segments = [];
  var adj = buildLayerConnections(portArc, sideNeighbors);
  var visited = new Array(tileArcs.length);
  var i;
  for (i = 0; i < tileArcs.length; i++) {
    visited[i] = false;
  }

  for (i = 0; i < tileArcs.length; i++) {
    if (visited[i]) continue;
    if (countArcDegree(adj, i) === 2) continue;
    var startEndpoint = adj[i][0] ? 1 : 0;
    var ordered = walkSegment(i, startEndpoint, adj, visited);
    if (ordered.length > 0) {
      segments.push(buildSegmentFromOrderedArcs(ordered, segments.length));
    }
  }

  for (i = 0; i < tileArcs.length; i++) {
    if (visited[i]) continue;
    var loopOrdered = walkSegment(i, 0, adj, visited);
    if (loopOrdered.length > 0) {
      segments.push(buildSegmentFromOrderedArcs(loopOrdered, segments.length));
    }
  }
}

function rebuildMesh() {
  var pad = CONFIG.pad;
  var innerW = Math.max(1, width - 2 * pad);
  var innerH = Math.max(1, height - 2 * pad);
  townMesh = buildTownscaperPixelGrid(innerW, innerH);
  meshBounds = bounds2d(townMesh.vertices);
  meshSpanX = meshBounds.maxX - meshBounds.minX;
  meshSpanY = meshBounds.maxY - meshBounds.minY;
  quadCount = townMesh.indices.length / 4;
  truchetType = new Uint8Array(quadCount);
  var i;
  var tileKind;
  var topBit;
  var adjacentVariant;
  for (i = 0; i < quadCount; i++) {
    tileKind = random() < 0.5 ? TILE_KIND_CROSS : TILE_KIND_ADJACENT;
    topBit = random() < 0.5 ? 0 : 1;
    adjacentVariant = random() < 0.5 ? 0 : 1;
    truchetType[i] = topBit | (tileKind << 1) | (adjacentVariant << 2);
  }
  assignStrands();
}

async function setup() {
  createCanvas(windowWidth > 0 ? windowWidth : 720, windowHeight > 0 ? windowHeight : 720);
  strokeJoin(ROUND);
  regenerateVariation(false);
  setupGlitchFilter();
  noLoop();
}

function draw() {
  colorMode(RGB, 255);
  background(CONFIG.bgColor);
  var pad = CONFIG.pad;
  var innerW = Math.max(1, width - 2 * pad);
  var innerH = Math.max(1, height - 2 * pad);
  var cx = (meshBounds.minX + meshBounds.maxX) / 2;
  var cy = (meshBounds.minY + meshBounds.maxY) / 2;

  push();
  translate(pad + innerW / 2, pad + innerH / 2);
  scale(1, -1);
  translate(-cx, -cy);

  var v = townMesh.vertices;
  var ix = townMesh.indices;
  var qi;
  var base;
  for (qi = 0; qi < quadCount; qi++) {
    base = qi * 4;
    var i0 = ix[base];
    var i1 = ix[base + 1];
    var i2 = ix[base + 2];
    var i3 = ix[base + 3];
    var p0 = v[i0];
    var p1 = v[i1];
    var p2 = v[i2];
    var p3 = v[i3];

    noStroke();
    fill(CONFIG.tileColor);
    quad(p0.x, p0.y, p1.x, p1.y, p2.x, p2.y, p3.x, p3.y);
  }

  var si;
  for (si = 0; si < segments.length; si++) {
    drawSegmentShadow(segments[si]);
  }

  for (si = 0; si < segments.length; si++) {
    if (segments[si].layer !== "under") continue;
    drawSegment(segments[si], strandColors[segments[si].strandId]);
  }

  var ci;
  for (ci = 0; ci < crossingContacts.length; ci++) {
    drawContactShadow(crossingContacts[ci]);
  }

  for (si = 0; si < segments.length; si++) {
    if (segments[si].layer !== "over") continue;
    drawSegment(segments[si], strandColors[segments[si].strandId]);
  }

  if (CONFIG.drawGridDebug) {
    noFill();
    stroke(CONFIG.gridDebugColor);
    strokeWeight(CONFIG.gridDebugLinePx);
    for (qi = 0; qi < quadCount; qi++) {
      base = qi * 4;
      var q0 = v[ix[base]];
      var q1 = v[ix[base + 1]];
      var q2 = v[ix[base + 2]];
      var q3 = v[ix[base + 3]];
      quad(q0.x, q0.y, q1.x, q1.y, q2.x, q2.y, q3.x, q3.y);
    }
  }
  pop();
  applyGlitchFilter();
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  rebuildMesh();
  setupGlitchFilter();
  redraw();
}

function keyPressed() {
  if (key === "r" || key === "R") {
    regenerateVariation(true);
  }
}

function mousePressed() {
  if (mouseButton === LEFT) {
    regenerateVariation(true);
  }
}


// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
